"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[34],{4034:(e,a,t)=>{t.d(a,{DI:()=>r,qu:()=>n,hG:()=>s});let i=JSON.parse('{"headlineLines":["Travel is the stage.","Stories are the product."],"highlightLineIndex":1,"subtext":"Karthik Thiramdas — a traveller and filmmaker telling cinematic stories across aviation, hotels, technology and travel, shooting and editing every frame himself with the discipline of a production.","primaryCta":{"label":"View the Work","href":"/work"},"secondaryCta":{"label":"The Studio","href":"/studio"}}'),l=JSON.parse('{"brand":"thekarthik","brandAccent":".io","links":[{"href":"/work","label":"Work"},{"href":"/industries","label":"Industries"},{"href":"/studio","label":"Studio"},{"href":"/journal","label":"Journal"},{"href":"/media-kit","label":"Media Kit"},{"href":"/contact","label":"Contact"}]}'),o=JSON.parse('{"hero":{"label":"Studio","context":"The Director\'s Statement","title":["One creator.","Every frame his own."],"intro":"Who I am, how I think, how I work, and what I carry to do it — in that order, because that\'s the order trust actually gets built in."},"whoIAm":{"headline":["Not a team.","One person, all the way through."],"paragraphs":["I\'m Karthik — a traveller and filmmaker based in Hyderabad. There\'s no crew standing off-camera and no agency behind the handle. I shoot it, I edit it, I color it, I write it, and I post it, on every single piece of work that carries my name.","That\'s not a limitation I work around. It\'s the entire point. A five-star cabin and a well-run production have the same thing in common — one clear standard, held by whoever is actually doing the work, every time. That\'s what \'studio\' means here: not a company, a discipline."],"index":"01","label":"Who I Am"},"howIThink":{"headline":["Trust before reach.","Craft before volume."],"intro":"Four principles that decide what gets made, and what gets left on the cutting-room floor.","index":"02","label":"How I Think"},"storytelling":{"headline":["Documentary instinct.","Cinematic execution."],"paragraphs":["The starting point is never \'what will perform\' — it\'s what\'s actually happening in front of the camera. A destination, a flight, a stay is treated as a story with its own shape, not a template to fill with establishing-shot-then-food-then-view.","That documentary instinct is what decides what to shoot. The cinematic execution — pacing, color, sound design — is what decides how it\'s cut. Both matter; neither substitutes for the other."],"pillars":[{"title":"Real, Not Staged","description":"Every trip, flight and stay in the work is one I\'ve genuinely experienced — the camera documents it, it doesn\'t direct it."},{"title":"One Idea Per Story","description":"Each piece earns its length by having something to say — a single throughline, not a highlight reel of unrelated moments."},{"title":"Sound Is Half the Film","description":"Pacing and music are cut together, not layered on afterward — a story\'s rhythm lives in the edit, not just the footage."}],"index":"03","label":"How I Approach Storytelling"},"workflow":{"headline":["From location","to final cut."],"intro":"The same six-stage process, whether it\'s a single Reel or a full destination film.","steps":[{"label":"01 \xb7 Plan","value":"Story & shot list"},{"label":"02 \xb7 Shoot","value":"On location, solo"},{"label":"03 \xb7 Select","value":"First-pass edit"},{"label":"04 \xb7 Edit","value":"Adobe Premiere Pro"},{"label":"05 \xb7 Grade & Score","value":"Color + Epidemic Sound"},{"label":"06 \xb7 Publish","value":"Platform-specific cut"}],"index":"04","label":"How I Work"},"gear":{"headline":["The kit, honestly.","Nothing borrowed for a post."],"intro":"Tools that help tell better stories — confirmed equipment this work is actually made with, not a technical catalogue.","categories":[{"name":"Camera / Mobile","items":[{"label":"Primary Camera","value":"Samsung Galaxy S24 Ultra 512GB"},{"label":"Secondary Device","value":"Samsung Galaxy S10+ 1TB"}]},{"name":"Audio","items":[{"label":"Microphone","value":"DJI Mic Mini"}]},{"name":"Stabilization","items":[{"label":"Smartphone Gimbal","value":"DJI Osmo Mobile 6"},{"label":"Flexible Tripod","value":"Syvo S11 Gorilla Tripod"},{"label":"Camera Tripod","value":"Ulanzi TT31"}]},{"name":"Lighting","items":[{"label":"LED Light","value":"Ulanzi VL49"},{"label":"Key Light","value":"Softbox"},{"label":"Fill","value":"Fill Light"},{"label":"Ambient","value":"Practical Lights"}]},{"name":"Storage","items":[{"label":"Portable SSD","value":"SanDisk 2TB"}]},{"name":"Editing & Post","items":[{"label":"Editing / Post-production","value":"MacBook M4"},{"label":"Edit Suite","value":"Adobe Premiere Pro"},{"label":"Music & Sound","value":"Epidemic Sound"}]}],"index":"05","label":"What I Shoot & Edit With"},"travelBag":{"headline":["The creator kit,","not the everyday bag."],"intro":"The confirmed gear above, as it\'s actually carried — not every item makes every trip, and the split between a full creator kit and an everyday travel bag isn\'t established yet, so this stays as one honest kit list.","items":[{"label":"Primary Camera","value":"Samsung Galaxy S24 Ultra 512GB"},{"label":"Secondary Device","value":"Samsung Galaxy S10+ 1TB"},{"label":"Microphone","value":"DJI Mic Mini"},{"label":"Gimbal","value":"DJI Osmo Mobile 6"},{"label":"Tripod","value":"Syvo S11 / Ulanzi TT31"},{"label":"Storage","value":"SanDisk 2TB SSD"}],"index":"06","label":"What\'s In My Bag"},"behindTheScenes":{"headline":["The process,","not just the result."],"intro":"A quiet look at what happens off-camera — reserved for behind-the-scenes photography as it\'s shot.","index":"07","label":"Behind the Work"},"cta":{"label":"What\'s Next","headline":"See the work this process actually produces.","subtext":"The same standard, applied across aviation, hotels, technology and travel.","primaryLabel":"View the Work","primaryHref":"/work","secondaryLabel":"Get in Touch","secondaryHref":"/contact"}}'),r=()=>i,n=()=>l,s=()=>o}}]);